const input = $('Start').first().json;
const cfg = $('Load prompt').first().json;
if (!cfg.automation_id) throw new Error(`Unknown automation "${input.automationId}"`);
if (!cfg.system_prompt) {
  throw new Error(`No ${input.promptVersion ? 'version ' + input.promptVersion : 'active version'} of prompt "${input.promptName}" for ${input.automationId}`);
}
const vars = input.vars || {};
const render = (t) => t.replace(/\{\{(\w+)\}\}/g, (_, k) => String(vars[k] ?? ''));
// Haiku 5.5: no temperature/top_p/top_k. Thinking tokens count toward max_tokens, so the default is generous.
return [{
  json: {
    automationId: cfg.automation_id,
    promptVersion: cfg.version,
    model: $env.CLAUDE_MODEL,
    schema: cfg.output_schema,
    startedAt: Date.now(),
    overBudget: cfg.spent_today >= cfg.budget,
    budget: cfg.budget,
    body: {
      model: $env.CLAUDE_MODEL,
      max_tokens: Number(input.maxTokens || 4096),
      output_config: { effort: input.effort || 'low' },
      system: cfg.system_prompt,
      messages: [{ role: 'user', content: render(cfg.user_template).slice(0, 30000) }],
    },
  },
}];

const req = $('Build request').first().json;
const error = `Daily AI budget of $${req.budget} reached for ${req.automationId}`;
return [{
  json: {
    ok: false, retryable: false, outcome: 'budget_exceeded', error,
    value: null, text: null, usage: { input: 0, output: 0 }, costUsd: 0,
    model: req.model, promptVersion: req.promptVersion, latencyMs: 0,
    params: [req.automationId, req.promptVersion, req.model, 'budget_exceeded', 0, 0, 0, 0, error],
  },
}];

const req = $('Build request').first().json;
const res = $input.first().json;
const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('').trim();
const usage = { input: res.usage?.input_tokens ?? 0, output: res.usage?.output_tokens ?? 0 };
const costUsd = Math.round(
  ((usage.input * Number($env.PRICE_INPUT_PER_MTOK) + usage.output * Number($env.PRICE_OUTPUT_PER_MTOK)) / 1e6) * 1e6,
) / 1e6;

// schema example: { "category": {"type":"enum","values":["a","b"]}, "confidence": {"type":"number","min":0,"max":1},
//                   "needs_human": {"type":"boolean"}, "draft_reply": {"type":"string","min":20,"max":3000} }
function validate(raw, schema) {
  if (!schema) return { ok: raw.length > 0, value: raw, problems: raw.length ? [] : ['empty'] };
  let s = raw;
  // Strip a markdown code fence if the model added one (three backticks, written as `{3}).
  const fenced = s.match(/`{3}(?:json)?\s*([\s\S]*?)`{3}/);
  if (fenced) s = fenced[1];
  let obj;
  try {
    obj = JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1));
  } catch {
    return { ok: false, value: null, problems: ['not_json'] };
  }
  const problems = [];
  for (const [key, rule] of Object.entries(schema)) {
    const v = obj[key];
    if (rule.type === 'enum' && !rule.values.includes(v)) problems.push(key);
    if (rule.type === 'number' && (typeof v !== 'number' || v < rule.min || v > rule.max)) problems.push(key);
    if (rule.type === 'boolean' && typeof v !== 'boolean') problems.push(key);
    if (rule.type === 'string' && (typeof v !== 'string' || v.trim().length < (rule.min ?? 0) || v.length > (rule.max ?? 100000))) problems.push(key);
  }
  return { ok: problems.length === 0, value: problems.length ? null : obj, problems };
}

const v = validate(text, req.schema);
// Haiku 5.5 can refuse (safety classifiers) or run out of max_tokens while thinking.
const stopProblem = res.stop_reason === 'refusal' ? 'refusal'
  : res.stop_reason === 'max_tokens' ? 'truncated' : null;
const ok = v.ok && !stopProblem;
const outcome = ok ? 'ok' : 'invalid_output';
const latencyMs = Date.now() - req.startedAt;
const problems = [...(stopProblem ? [stopProblem] : []), ...v.problems];
const error = ok ? null : `invalid_output:${problems.join(',')}`;
return [{
  json: {
    ok, retryable: false, outcome, error, value: ok ? v.value : null, text, usage, costUsd,
    model: req.model, promptVersion: req.promptVersion, latencyMs,
    params: [req.automationId, req.promptVersion, req.model, outcome,
             usage.input, usage.output, costUsd, latencyMs, error],
  },
}];

const req = $('Build request').first().json;
const item = $input.first().json;
const message = (typeof item.error === 'string' ? item.error : item.error?.message || 'unknown error').slice(0, 300);
const latencyMs = Date.now() - req.startedAt;
return [{
  json: {
    ok: false, retryable: true, outcome: 'failed', error: message,
    value: null, text: null, usage: { input: 0, output: 0 }, costUsd: 0,
    model: req.model, promptVersion: req.promptVersion, latencyMs,
    params: [req.automationId, req.promptVersion, req.model, 'failed', 0, 0, 0, latencyMs, message],
  },
}];

// Only one of the three result nodes ran; find it.
const pick = (name) => {
  try { return $(name).first().json; } catch { return null; }
};
const r = pick('Validate output') ?? pick('Call failed') ?? pick('Budget result');
const { params, ...result } = r;
return [{ json: result }];
